from openai import RateLimitError
import time

def retry_with_backoff(func, max_retries=3):
    for attempt in range(max_retries):
        try:
            return func()
        except RateLimitError:
            if attempt == max_retries - 1:
                raise
            time.sleep(2 ** attempt)
    return None

# Mock function that always raises RateLimitError
def mock_call():
    raise RateLimitError('', response=type('r',(),{'status_code':429})(), body=None)

try:
    retry_with_backoff(mock_call, max_retries=2)
except RateLimitError:
    print("Rate limit persisted")

